from pathlib import Path
import re
from collections import defaultdict

# Redefine file paths
file_paths = [
    "/mnt/data/CHAT 1.0 DATE.txt",
    "/mnt/data/CHAT 1.25 DATE.txt",
    "/mnt/data/CHAT 1.5 DATE.txt",
    "/mnt/data/CHAT 1.75 DATE.txt",
    "/mnt/data/CHATS 2 DATE.txt",
    "/mnt/data/CHATS 3 DATE.txt",
    "/mnt/data/CHATS 4 DATE.txt"
]

# Define years to search for
years = ["2020", "2021", "2022", "2023", "2024", "2025"]

# Function to classify temporal reference
def classify_line(line, year):
    line_lower = line.lower()
    if any(w in line_lower for w in ["next year", "will", "going to", f"by {year}", f"in {year}"]):
        return "Tf"
    elif any(w in line_lower for w in ["last year", "was", "used to", "earlier", f"in {year}"]):
        return "Tp"
    else:
        return None

# Analyze each file
summary = []

for path in file_paths:
    filename = Path(path).name
    lines = Path(path).read_text(errors='ignore').splitlines()
    year_mentions = {year: set() for year in years}

    for line in lines:
        for year in years:
            if year in line:
                tag = classify_line(line, year)
                if tag:
                    year_mentions[year].add(tag)

    row = []
    for year in years:
        tags = year_mentions[year]
        if "Tp" in tags and "Tf" in tags:
            row.append("<>")
        elif "Tp" in tags:
            row.append("<")
        elif "Tf" in tags:
            row.append(">")
        else:
            row.append("--")
    summary.append((filename, *row))

# Create a dataframe for the results
df_summary = pd.DataFrame(summary, columns=["File"] + years)

import ace_tools as tools; tools.display_dataframe_to_user(name="Year Mentions Summary (Tp/Tf)", dataframe=df_summary)
